    DAILY_SALARY = 80
    budget = my_status['budget']
    hp = my_status['hp']
    no_water_days = my_status['no_water_days']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Collect yesterday's bids from all opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    if hp <= 2 or no_water_days >= 2:
        # Urgent need for water
        base_bid = DAILY_SALARY * 0.9
    elif yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        if max_prev_bid >= DAILY_SALARY * 0.85:
            # Yesterday's high bid suggests aggressive opponents; be conservative
            base_bid = DAILY_SALARY * 0.4
        else:
            # Match or slightly exceed yesterday's highest
            base_bid = max(DAILY_SALARY * 0.5, max_prev_bid + 1.5)
    else:
        # First day or no data: moderate bid
        base_bid = DAILY_SALARY * 0.5

    # Ensure bid does not exceed budget
    return min(budget, base_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_budget = float(my_status.get('budget', 0.0))
    my_hp = float(my_status.get('hp', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp and opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents, bid conservatively.
    if not alive_opponents:
        bid = DAILY_SALARY * 0.35
        return max(0.0, min(my_budget, bid))

    # Read yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how many full WATER_REQ blocks exist in supply.
    # Use int() to prevent float indices elsewhere.
    supply_int = int(supply)
    full_blocks = max(0, supply_int // int(WATER_REQ))

    # Base bid depends on supply pressure.
    # If supply is tight (near MIN_SUPPLY), increase bids.
    if supply_int <= MIN_SUPPLY:
        base = DAILY_SALARY * 0.62
    elif supply_int >= MAX_SUPPLY:
        base = DAILY_SALARY * 0.45
    else:
        # interpolate linearly between MIN_SUPPLY..MAX_SUPPLY
        t = (supply - float(MIN_SUPPLY)) / max(1e-9, float(MAX_SUPPLY - MIN_SUPPLY))
        base = DAILY_SALARY * (0.62 - 0.17 * t)

    # React to opponents' yesterday bids.
    # If they were bidding aggressively (near salary), we assume they are under pressure.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))

        aggressive_threshold = DAILY_SALARY * 0.82
        if highest_prev_bid >= aggressive_threshold:
            # They likely need water; bid slightly above their typical aggressive level.
            bid = max(base, highest_prev_bid + 2.0)
        else:
            # They were not extremely aggressive; bid around base but tilt toward avg.
            bid = max(base, avg_prev_bid + 1.5)
    else:
        bid = base

    # If my HP is critical or I already missed water days, bid higher to avoid further HP loss.
    # Conversely, if HP is good and I have budget, keep bid moderate.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        bid *= 1.18
    elif my_hp >= 6.0 and my_no_water_days == 0:
        bid *= 0.92

    # If supply has very few full blocks, we should fight more for scarce water.
    if full_blocks <= 1:
        bid *= 1.12

    # Cap bid by what we can afford.
    bid = max(0.0, min(my_budget, bid))

    # Always keep a minimum presence to avoid being shut out when supply is tight.
    # Minimum is a fraction of daily salary but not exceeding budget.
    min_presence = DAILY_SALARY * 0.25
    if bid < min_presence and my_budget > 0:
        bid = min(my_budget, min_presence)

    return float(bid)
